// Generates the Flutter and web token files from nithya.tokens.json.
// Usage: node tokens/build.mjs [--check]   (--check fails if generated files are stale)
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const t = JSON.parse(fs.readFileSync(path.join(root, 'tokens/nithya.tokens.json'), 'utf8'));
const header = 'GENERATED by tokens/build.mjs from tokens/nithya.tokens.json. Do not edit.';

const hex = (c) => {
  if (!/^#[0-9a-fA-F]{6}$/.test(c)) throw new Error(`bad colour ${c}`);
  return c.slice(1).toUpperCase();
};
const dartColor = (c) => `Color(0xFF${hex(c)})`;
const rgba = (c, a) => {
  const n = parseInt(hex(c), 16);
  return `rgba(${n >> 16}, ${(n >> 8) & 255}, ${n & 255}, ${a})`;
};
const dartReserved = new Set(['new', 'default', 'class', 'switch', 'is', 'in', 'var', 'const', 'final']);
const dartName = (k) => (dartReserved.has(k) ? `${k}_` : k);
const num = (n) => (Number.isInteger(n) ? `${n}.0` : `${n}`);
const css = (name) => name.replace(/[A-Z]/g, (m) => '-' + m.toLowerCase());
const families = { display: t.font.display, body: t.font.body };
const themeNames = Object.keys(t.themes);

function dart() {
  // `dart format off` keeps --check stable: dart format would rewrap this file.
  const out = [`// ${header}`, '// dart format off', '', "import 'package:flutter/widgets.dart';", '', "import 'palette.dart';", ''];
  const group = (cls, doc, entries, fmt) => {
    out.push(`/// ${doc}`, `abstract final class ${cls} {`);
    for (const [k, v] of Object.entries(entries)) out.push(`  static const ${fmt(dartName(k), v)};`);
    out.push('}', '');
  };
  group('NithyaFonts', 'Font families bundled with the package.', families, (k, v) => `${k} = '${v}'`);
  group('NithyaSpace', 'Spacing steps in logical pixels.', t.space, (k, v) => `double ${k} = ${num(v)}`);
  group('NithyaRadius', 'Corner radius steps in logical pixels.', t.radius, (k, v) => `double ${k} = ${num(v)}`);
  group('NithyaSize', 'Fixed component sizes in logical pixels.', t.size, (k, v) => `double ${k} = ${num(v)}`);
  group('NithyaMotion', 'Animation durations.', t.motion, (k, v) => `Duration ${k} = Duration(milliseconds: ${v})`);
  group('NithyaAccent', 'Theme-independent accent colours.', t.accent, (k, v) => `Color ${k} = ${dartColor(v)}`);
  group('NithyaHues', 'Per-tool icon hues.', t.hues, (k, v) => `Color ${k} = ${dartColor(v)}`);
  out.push('/// Every tool hue by name, in token order.', 'const nithyaHues = <String, Color>{');
  for (const k of Object.keys(t.hues)) out.push(`  '${k}': NithyaHues.${k},`);
  out.push('};', '');
  group('NithyaBadgeHues', 'Hue used by each status badge.', t.badges, (k, v) => `Color ${k} = NithyaHues.${v}`);
  out.push('/// Type scale.', 'abstract final class NithyaType {');
  for (const [k, s] of Object.entries(t.type)) {
    out.push(
      `  static const ${k} = NithyaTypeSpec(family: NithyaFonts.${s.family}, size: ${num(s.size)}, ` +
        `weight: FontWeight.w${s.weight}, tracking: ${num(s.tracking)}, height: ${num(s.height)});`,
    );
  }
  out.push('}', '');
  out.push('/// Built-in palettes by name. The first entry is the default.', 'const nithyaPalettes = <String, NithyaPalette>{');
  for (const [name, p] of Object.entries(t.themes)) {
    out.push(`  '${name}': NithyaPalette(`, `    name: '${name}',`, `    label: '${p.label}',`);
    out.push(`    brightness: Brightness.${p.brightness},`);
    for (const k of ['background', 'panel', 'panelBorder', 'modal', 'controls', 'controlsBorder', 'foreground', 'muted', 'divider'])
      out.push(`    ${k}: ${dartColor(p[k])},`);
    out.push(`    scrim: ${dartColor(p.scrim)},`, `    scrimAlpha: ${num(p.scrimAlpha)},`);
    out.push(`    photoTint: ${dartColor(p.photoTint)},`, `    photoTintAlpha: ${num(p.photoTintAlpha)},`);
    out.push(`    photoGrayscale: ${p.photoGrayscale},`);
    out.push(`    glow: [`);
    for (const g of p.glow)
      out.push(`      NithyaGlow(color: ${dartColor(g.color)}, alpha: ${num(g.alpha)}, x: ${num(g.x)}, y: ${num(g.y)}, radius: ${num(g.radius)}),`);
    out.push('    ],', '  ),');
  }
  out.push('};', '');
  return out.join('\n');
}

function webCss() {
  const fam = (f) => `"${f}", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif`;
  const out = [`/* ${header} */`, '', ':root {'];
  out.push(`  --n-font-display: ${fam(t.font.display)};`, `  --n-font-body: ${fam(t.font.body)};`);
  for (const [k, s] of Object.entries(t.type)) {
    out.push(`  --n-type-${k}-family: var(--n-font-${s.family});`, `  --n-type-${k}-size: ${s.size}px;`);
    out.push(`  --n-type-${k}-weight: ${s.weight};`, `  --n-type-${k}-tracking: ${s.tracking}px;`, `  --n-type-${k}-height: ${s.height};`);
  }
  for (const [k, v] of Object.entries(t.space)) out.push(`  --n-space-${k}: ${v}px;`);
  for (const [k, v] of Object.entries(t.radius)) out.push(`  --n-radius-${k}: ${v}px;`);
  for (const [k, v] of Object.entries(t.size)) out.push(`  --n-size-${css(k)}: ${v}px;`);
  for (const [k, v] of Object.entries(t.motion)) out.push(`  --n-motion-${k}: ${v}ms;`);
  for (const [k, v] of Object.entries(t.accent)) out.push(`  --n-${css(k)}: #${hex(v)};`);
  for (const [k, v] of Object.entries(t.hues)) out.push(`  --n-hue-${k}: #${hex(v)};`);
  for (const [k, v] of Object.entries(t.badges)) out.push(`  --n-badge-${k}: var(--n-hue-${v});`);
  out.push('}', '');
  themeNames.forEach((name, i) => {
    const p = t.themes[name];
    const sel = i === 0 ? `:root,\n[data-nithya-theme='${name}']` : `[data-nithya-theme='${name}']`;
    out.push(`${sel} {`, `  color-scheme: ${p.brightness};`);
    for (const k of ['background', 'panel', 'panelBorder', 'modal', 'controls', 'controlsBorder', 'foreground', 'muted', 'divider'])
      out.push(`  --n-${css(k)}: #${hex(p[k])};`);
    out.push(`  --n-scrim: ${rgba(p.scrim, p.scrimAlpha)};`);
    out.push(`  --n-photo-tint: ${rgba(p.photoTint, p.photoTintAlpha)};`);
    out.push(`  --n-photo-filter: ${p.photoGrayscale ? 'grayscale(1)' : 'none'};`);
    const layers = p.glow.map(
      (g) => `radial-gradient(circle ${g.radius}px at ${+(g.x * 100).toFixed(2)}% ${+(g.y * 100).toFixed(2)}%, ${rgba(g.color, g.alpha)}, transparent)`,
    );
    out.push(`  --n-backdrop: ${[...layers, `#${hex(p.background)}`].join(', ')};`, '}', '');
  });
  return out.join('\n');
}

function webTs() {
  const labels = themeNames.map((n) => `  ${n}: '${t.themes[n].label}',`).join('\n');
  return [
    `// ${header}`,
    '',
    `export const themeNames = [${themeNames.map((n) => `'${n}'`).join(', ')}] as const;`,
    'export type ThemeName = (typeof themeNames)[number];',
    '',
    `export const themeLabels: Record<ThemeName, string> = {\n${labels}\n};`,
    '',
    `export const hueNames = [${Object.keys(t.hues).map((n) => `'${n}'`).join(', ')}] as const;`,
    'export type HueName = (typeof hueNames)[number];',
    '',
  ].join('\n');
}

const files = {
  'flutter/lib/src/tokens.g.dart': dart(),
  'web/src/nithya/tokens.css': webCss(),
  'web/src/nithya/tokens.ts': webTs(),
};
const check = process.argv.includes('--check');
let stale = 0;
for (const [rel, body] of Object.entries(files)) {
  const file = path.join(root, rel);
  const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
  if (current === body) continue;
  if (check) {
    console.error(`stale: ${rel}`);
    stale++;
  } else {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, body);
    console.log(`wrote ${rel}`);
  }
}
if (stale) process.exit(1);
